"""Command line interface for logscan."""

import argparse
import json
import sys
from collections import Counter

from . import __version__
from . import parser as _parser


def build_parser():
    ap = argparse.ArgumentParser(
        prog="logscan", description="Tiny log analysis toolkit."
    )
    ap.add_argument(
        "--version", action="version", version="logscan " + __version__
    )
    sub = ap.add_subparsers(dest="command", required=True)

    ap_count = sub.add_parser(
        "count", help="Count parseable records in a log file."
    )
    ap_count.add_argument("path")

    ap_stats = sub.add_parser(
        "stats",
        help="Compute aggregate statistics for a log file.",
        description="Compute aggregate statistics for a log file.",
    )
    ap_stats.add_argument("path")
    ap_stats.add_argument("--top", type=_non_negative_int, default=3)

    return ap


def _non_negative_int(value):
    try:
        number = int(value)
    except ValueError as exc:
        raise argparse.ArgumentTypeError("must be an integer") from exc
    if number < 0:
        raise argparse.ArgumentTypeError("must be non-negative")
    return number


def _read_records(path):
    with open(path, "r", encoding="utf-8") as fh:
        return _parser.parse_lines(fh)


def _stats(records, top):
    message_counts = Counter(message for _level, message in records)
    top_messages = sorted(
        message_counts,
        key=lambda message: (-message_counts[message], message),
    )[:top]
    return {
        "total": len(records),
        "by_level": _parser.count_levels(records),
        "unique_messages": len(message_counts),
        "top_messages": top_messages,
    }


def main(argv=None):
    args = build_parser().parse_args(argv)
    if args.command == "count":
        print(len(_read_records(args.path)))
        return 0
    if args.command == "stats":
        try:
            records = _read_records(args.path)
        except FileNotFoundError:
            print(
                f"logscan: error: no such file: {args.path}",
                file=sys.stderr,
            )
            return 3
        print(json.dumps(_stats(records, args.top)))
        return 0
    return 2


if __name__ == "__main__":
    sys.exit(main())
